describe('In-App Notifications', () => {
    beforeEach(() => {
        cy.visit('/notifications');
    });

    it('should display new notifications in real-time', () => {
        // Simulate receiving a new notification
        cy.intercept('POST', '/api/notifications', { fixture: 'newNotification.json' }).as('newNotification');

        // Trigger the event that causes a new notification to be sent
        cy.get('button#send-notification').click();

        // Wait for the notification to be received
        cy.wait('@newNotification');

        // Check if the new notification appears in the notifications list
        cy.get('.notification-list').should('contain', 'You have a new message!');
    });

    it('should not display duplicate notifications', () => {
        // Simulate receiving the same notification twice
        cy.intercept('POST', '/api/notifications', { fixture: 'duplicateNotification.json' }).as('duplicateNotification');

        // Trigger the event that causes the duplicate notification to be sent
        cy.get('button#send-duplicate-notification').click();

        // Wait for the notification to be received
        cy.wait('@duplicateNotification');

        // Check if the duplicate notification does not appear again
        cy.get('.notification-list').should('have.length', 1);
    });
});
